-- Programação reescrita a partir de programacaomindsummit2026.xlsx
-- (Adriana, 2026-08-22). As colunas passam a espelhar as da planilha:
-- dia, horário (inicio/fim), ingressos, local, conteúdo (titulo/descricao),
-- palestrantes e duração.
--
-- Estrutura mantida de propósito: palestrante continua em mind.speakers,
-- ligado por mind.session_speakers. Os 42 palestrantes aparecem em 67
-- sessões com muita repetição (Amy Edmondson em 3, Carla Tieppo em 3) e a
-- bio precisa existir uma vez só. O PAPEL é da ligação, não da pessoa:
-- Denize Savi media um painel e palestra em outro.
--
-- 'ingressos' é coluna nova e é o que faltava para o agente responder
-- "esse workshop é VIP e Prime" sem deduzir do nome da sala.
-- mind.session_reservations está vazia: não há reserva de participante a
-- preservar na reescrita.

alter table mind.sessions
  add column if not exists ingressos text[] not null default '{}',
  add column if not exists duracao_min integer;

comment on column mind.sessions.ingressos is
  'Quais experiências dão acesso a esta sessão. É o que permite ao agente dizer "esse workshop é VIP e Prime".';

alter table mind.session_speakers
  add column if not exists papel text not null default 'palestrante'
    check (papel in ('palestrante','mediacao','apresentacao','convidado'));

comment on column mind.session_speakers.papel is
  'Papel nesta sessão específica. Quem media um painel palestra em outro.';

create table if not exists mind._import_programacao (j jsonb);
truncate mind._import_programacao;
